var e={"hund-schlaf":[`David Shankbone from USA`,`CC BY 2.0`],"baby-gaehnt":[`Martin Falbisoner`,`CC BY-SA 4.0`],schach:[`Dietmar Rabich`,`CC BY-SA 4.0`],marshmallows:[`John Morgan`,`CC BY 2.0`],"e-coli":[`NIAID`,`gemeinfrei`],"giraffen-necking":[`Luca Galuzzi (Lucag)`,`CC BY-SA 2.5`],"mrt-gehirn":[`Asnaebsa`,`CC BY-SA 4.0`],spinat:[`Nillerdk`,`CC BY 3.0`],"newton-baum":[`Richard Croft`,`CC BY-SA 2.0`],apfelbaum:[`W.carter`,`CC0`],orion:[`Igor da Bari`,`CC BY 4.0`],"gps-satellit":[`NASA`,`gemeinfrei`],goldbarren:[`Szaaman`,`gemeinfrei`],"lachendes-kind":[`Katie Thomas`,`CC BY 2.0`],"gjermundbu-helm":[`Wolfmann`,`CC BY-SA 4.0`],"veksoe-helm":[`Nationalmuseet, Roberto Fortuna og Kira Ursem`,`CC BY-SA 3.0`],"napoleon-hut":[`Wolfgang Sauber`,`CC BY-SA 3.0`],"blaue-murmel":[`NASA, Apollo 17`,`gemeinfrei`],gizeh:[`Ricardo Liberato`,`CC BY-SA 2.0`],"sokrates-buste":[`Louvre (Foto)`,`gemeinfrei`],"pithoi-knossos":[`Moonik`,`CC BY-SA 3.0`],weiche:[`W.carter`,`gemeinfrei`],"marc-aurel":[`Nicholas Hartmann`,`CC BY-SA 4.0`],sanduhr:[`John Morgan`,`CC BY 2.0`],laeufer:[`Chris Hunkeler`,`CC BY-SA 2.0`],"globe-theatre":[`Txllxt TxllxT`,`CC BY-SA 4.0`],lego:[`Alan Chia`,`CC BY-SA 2.0`],maerchenwald:[`Vad 7`,`CC BY 3.0`],"mona-lisa-louvre":[`Julian Lupyan`,`CC0`],sonnenblumen:[`Björn S.`,`CC BY-SA 3.0`],geige:[`Daniel Jason Karjadi`,`CC BY-SA 2.0`],rijksmuseum:[`Frans de Wit`,`CC BY-SA 2.0`],"reiten-wald":[`Steve Daniels`,`CC BY-SA 2.0`],gerichtssaal:[`U.S. Air Force`,`gemeinfrei`],"nato-flaggen":[`U.S. Department of Defense`,`gemeinfrei`],wahlurne:[`W.carter`,`CC BY-SA 4.0`],tulpenfeld:[`acediscovery`,`CC BY 4.0`],kobra:[`Dr. Raju Kasambe`,`CC BY-SA 4.0`],euro:[`Friedrich Haag`,`CC BY-SA 4.0`],preisschilder:[`DemieK07`,`CC BY 4.0`],goldfisch:[`James St. John`,`CC BY 2.0`],bibliothek:[`Gary Todd`,`CC0`],storch:[`Charles J. Sharp`,`CC BY-SA 4.0`],ziege:[`Ali`,`CC BY 2.0`],everest:[`Luca Galuzzi (Lucag)`,`CC BY-SA 2.5`],"chinesische-mauer":[`Velatrix`,`CC0`],"erde-nachts":[`NASA Johnson Space Center`,`gemeinfrei`],"pompeji-vesuv":[`Commonists`,`CC BY-SA 4.0`],"gefrorene-gracht":[`Donald Trung Quoc Don`,`CC BY-SA 4.0`],motte:[`Arthur Chapman`,`CC BY 2.0`],"gutenberg-bibel":[`Joshua Keller`,`CC BY 2.0`],gluehfaden:[`Jules Verne Times Two`,`CC BY-SA 4.0`],"turing-statue":[`DeFacto`,`CC BY-SA 4.0`],"blitz-eiffelturm":[`Gabriel Loppé`,`gemeinfrei`],"logbuch-bug":[`U.S. Naval History and Heritage Command`,`gemeinfrei`]};function t(t){let[n,r]=e[t];return{file:`${t}.webp`,author:n,license:r}}var n=[{id:`hoernerhelm`,area:`GESCH`,day:31,hook:`Trugen Wikinger Helme mit Hörnern?`,mood:`episch`,ambience:`wellen`,images:[t(`gjermundbu-helm`),t(`veksoe-helm`)],slides:[{text:`Kein einziger **Hörnerhelm** aus der Wikingerzeit wurde je gefunden. Der einzige fast vollständige Wikingerhelm, der Gjermundbu-Helm aus Norwegen, ist schlicht rund.`},{text:`Das Bild stammt aus dem 19. Jahrhundert: Maler der **Romantik** und vor allem die Kostüme zu Wagners „Ring des Nibelungen“ 1876 setzten den Wikingern Hörner auf. Seitdem sind sie nicht mehr wegzukriegen.`,cam:[50,45,1.3]},{text:`Hörnerhelme gab es – aber viel früher: In Dänemark fand man die **Veksø-Helme** aus der Bronzezeit, rund 2.900 Jahre alt, fast 2.000 Jahre vor den Wikingern. Im Kampf wären Hörner nur hinderlich.`,img:1}],verdict:`hype`,why:`Kein archäologischer Fund. Der Mythos stammt aus Malerei und Oper des 19. Jahrhunderts.`,summary:[`Kein Wikingerhelm mit Hörnern gefunden.`,`Wagner-Kostüme 1876 prägten das Bild.`,`Hörnerhelme gab es in der Bronzezeit.`],sources:[`Nationalmuseet Kopenhagen: Veksø-Helme`,`Kulturhistorisk museum Oslo: Gjermundbu-Helm`]},{id:`napoleon`,area:`GESCH`,day:40,hook:`War Napoleon wirklich so klein?`,mood:`episch`,images:[t(`napoleon-hut`)],slides:[{text:`Napoleon maß bei seinem Tod rund **1,69 Meter** – für einen Franzosen um 1800 eher Durchschnitt. Der Irrtum: Sein Maß stand in französischen Zoll, und die waren länger als englische.`},{text:`Den Rest erledigte **Propaganda**: Britische Karikaturisten wie James Gillray zeichneten ihn als winzigen, wütenden „Little Boney“. Dazu nannten ihn seine Soldaten liebevoll „le petit caporal“ – den kleinen Korporal.`,cam:[50,45,1.35]},{text:`Napoleon selbst ließ sich ganz anders malen: Bei Jacques-Louis David reitet er auf einem **steigenden Hengst** über die Alpen. In Wahrheit überquerte er den Pass auf einem Maultier.`}],verdict:`hype`,why:`Napoleon war durchschnittlich groß – das Bild vom kleinen Kaiser ist ein Erfolg britischer Karikaturen.`,summary:[`Rund 1,69 m: Durchschnitt für seine Zeit.`,`Französische Zoll waren länger als englische.`,`Karikaturen machten ihn klein, Gemälde groß.`],sources:[`Encyclopaedia Britannica: Napoleon I`,`British Museum: Gillray, The Plumb-pudding in danger (1805)`]},{id:`flache-erde`,area:`GESCH`,day:31,hook:`Hielt man im Mittelalter die Erde für eine Scheibe?`,mood:`raetsel`,ambience:`weltraum`,images:[t(`blaue-murmel`)],slides:[{text:`Nein – Gebildete wussten seit der Antike, dass die Erde eine **Kugel** ist. Eratosthenes berechnete um 240 v. Chr. sogar ihren Umfang, erstaunlich genau.`},{text:`Im Mittelalter lehrten Gelehrte wie Beda oder Thomas von Aquin die Kugelgestalt. Könige hielten den **Reichsapfel** in der Hand – eine Kugel als Zeichen der Welt.`,cam:[45,45,1.3]},{text:`Der Mythos entstand im **19. Jahrhundert**: Autoren wie Washington Irving schmückten die Kolumbus-Geschichte aus, als hätte er gegen Flacherde-Gläubige gekämpft. Gestritten wurde 1492 aber über die Größe der Erde – und da lag Kolumbus falsch.`}],verdict:`hype`,why:`Mittelalterliche Quellen beschreiben fast durchweg eine Kugel. Die Flache-Erde-Legende ist neuzeitlich.`,summary:[`Kugelgestalt seit der Antike bekannt.`,`Reichsapfel = Welt als Kugel.`,`Kolumbus irrte bei der Größe, nicht bei der Form.`],sources:[`Russell 1991, Inventing the Flat Earth`]},{id:`pyramiden`,area:`GESCH`,day:18,hook:`Bauten Sklaven die Pyramiden?`,mood:`raetsel`,ambience:`wind`,images:[t(`gizeh`)],slides:[{text:`So zeigen es Hollywood-Filme: Peitschen, Ketten, Tausende **Sklaven**. Die Archäologie erzählt etwas anderes.`},{text:`Bei Gizeh fand man die **Arbeiterstadt**: Bäckereien, Brauereien, Unterkünfte – und Gräber der Arbeiter direkt neben den Pyramiden. Sklaven hätte man nie so ehrenvoll bestattet.`,cam:[40,55,1.4]},{text:`Die Knochen zeigen schwere Arbeit, aber auch **Medizin**: verheilte Brüche, sogar Amputationen. Die Arbeiter bekamen Brot, Bier und Fleisch. Viele waren Bauern, die abwechselnd Dienst taten.`}],verdict:`hype`,why:`Funde in Gizeh zeigen versorgte Arbeiter mit eigenen Gräbern – keine Sklavenheere.`,summary:[`Arbeiterstadt und Gräber neben den Pyramiden.`,`Brot, Bier, Fleisch und medizinische Versorgung.`,`Viele Bauern arbeiteten im Wechsel.`],sources:[`Lehner & Hawass 2017, Giza and the Pyramids`,`AERA: Lost City of the Pyramid Builders`]},{id:`erlaubt`,area:`POL`,day:15,hook:`Ist in Deutschland alles verboten, was nicht erlaubt ist?`,mood:`ruhig`,ambience:`wind`,images:[t(`reiten-wald`)],slides:[{text:`Viele glauben das – es ist umgekehrt. Artikel 2 des Grundgesetzes schützt die **allgemeine Handlungsfreiheit**: Du darfst alles tun, was nicht verboten ist.`},{text:`Für den **Staat** gilt das Gegenteil: Behörden dürfen in deine Rechte nur eingreifen, wenn ein Gesetz es erlaubt. Juristen nennen das den Vorbehalt des Gesetzes.`,cam:[50,50,1.35]},{text:`Wie weit das reicht, zeigt ein Urteil von 1989: Selbst **Reiten im Wald** fällt unter diese Freiheit – darf aber per Gesetz eingeschränkt werden. Die Entscheidung heißt seitdem „Reiten im Walde“.`}],verdict:`hype`,why:`Für Bürger gilt: erlaubt ist, was nicht verboten ist. Nur der Staat braucht für jeden Eingriff eine Grundlage.`,summary:[`Art. 2 GG: allgemeine Handlungsfreiheit.`,`Behörden brauchen eine gesetzliche Grundlage.`,`Urteil „Reiten im Walde“, 1989.`],sources:[`Grundgesetz Art. 2 Abs. 1, Art. 20 Abs. 3`,`BVerfGE 80, 137`]},{id:`unwissenheit`,area:`POL`,day:75,hook:`Schützt Unwissenheit vor Strafe?`,mood:`raetsel`,images:[t(`gerichtssaal`)],slides:[{text:`Das Sprichwort sagt: nein. Im deutschen Strafrecht ist es feiner. Wer nicht weiß, dass etwas **verboten** ist, irrt sich über das Verbot – juristisch ein Verbotsirrtum.`},{text:`Nach Paragraf 17 Strafgesetzbuch bleibt man nur straffrei, wenn der Irrtum **unvermeidbar** war. Wer sich hätte erkundigen können – bei einer Anwältin oder einer Behörde –, wird bestraft, höchstens milder.`,cam:[50,45,1.3]},{text:`Anders beim **Irrtum über Tatsachen**: Wer einen fremden Schirm für seinen eigenen hält, stiehlt nicht – ihm fehlt der Vorsatz. Er kennt nicht das Gesetz nicht, sondern die Lage.`}],verdict:`belegt`,why:`Nur ein unvermeidbarer Verbotsirrtum entschuldigt – und der ist im Alltag fast nie unvermeidbar.`,summary:[`§ 17 StGB: Verbotsirrtum.`,`Straffrei nur, wenn unvermeidbar.`,`Irrtum über Tatsachen (§ 16) lässt den Vorsatz entfallen.`],sources:[`Strafgesetzbuch §§ 16, 17`]},{id:`nato-artikel-5`,area:`POL`,day:64,hook:`Muss die NATO bei einem Angriff automatisch in den Krieg?`,mood:`episch`,ambience:`wind`,images:[t(`nato-flaggen`)],slides:[{text:`Artikel 5 des NATO-Vertrags: Ein bewaffneter Angriff auf ein Mitglied gilt als **Angriff auf alle**. Das klingt nach Automatik.`},{text:`Im Text steht aber: Jedes Land leistet Beistand mit den Maßnahmen, **die es für erforderlich hält** – einschließlich Waffengewalt. Wie geholfen wird, entscheidet jedes Land selbst.`,cam:[50,40,1.3]},{text:`Ausgerufen wurde der Bündnisfall bisher nur **einmal**: nach den Anschlägen vom 11. September 2001 – zum Schutz der USA.`}],verdict:`hype`,why:`Artikel 5 verpflichtet zum Beistand, lässt aber jedem Land die Wahl der Mittel.`,summary:[`Angriff auf einen = Angriff auf alle.`,`Jedes Land wählt die Mittel selbst.`,`Bündnisfall bisher nur 2001.`],sources:[`Nordatlantikvertrag 1949, Art. 5`,`NATO: Collective defence and Article 5`]},{id:`wahlpflicht`,area:`POL`,day:15,hook:`Würden mehr Leute wählen, wenn sie müssten?`,mood:`verspielt`,images:[t(`wahlurne`)],slides:[{text:`In **Australien** gilt seit 1924 Wahlpflicht. Wer ohne Grund fehlt, zahlt ein kleines Bußgeld. Die Beteiligung liegt seitdem meist um 90 Prozent.`},{text:`In Deutschland lag sie bei der Bundestagswahl 2025 bei rund **82 Prozent** – so hoch wie seit Jahrzehnten nicht. Bei Landtags- und Europawahlen ist sie oft viel niedriger.`,cam:[50,45,1.35]},{text:`Studien zeigen: Wahlpflicht erhöht die Beteiligung zuverlässig und gleicht sie zwischen **Arm und Reich** an. Ob die Leute dadurch informierter wählen, ist offen.`}],verdict:`belegt`,why:`Länder mit durchgesetzter Wahlpflicht haben deutlich höhere und sozial ausgeglichenere Beteiligung.`,summary:[`Australien: Wahlpflicht seit 1924, rund 90 % Beteiligung.`,`Bundestagswahl 2025: rund 82 %.`,`Pflicht gleicht Unterschiede zwischen Arm und Reich an.`],sources:[`Australian Electoral Commission`,`Die Bundeswahlleiterin 2025`,`Lijphart 1997, American Political Science Review`]},{id:`tulpenmanie`,area:`WIRT`,day:28,hook:`Ruinierte die Tulpenmanie ganz Holland?`,mood:`verspielt`,images:[t(`tulpenfeld`)],slides:[{text:`1637 erreichten **Tulpenzwiebeln** in den Niederlanden absurde Preise – eine einzige Zwiebel der Sorte „Semper Augustus“ soll so viel gekostet haben wie ein Haus. Dann brach der Markt in wenigen Tagen ein.`},{text:`Lange galt das als erste **Spekulationsblase** mit ruinierten Existenzen. Die Historikerin Anne Goldgar fand in den Archiven aber kaum Pleiten: Gehandelt hatte eine kleine Schicht reicher Kaufleute, viele Verträge wurden nie erfüllt.`,cam:[50,60,1.35]},{text:`Die Horror-Geschichten stammen oft aus **moralischen Flugschriften** der Zeit – und aus dem Bestseller von Charles Mackay, 1841. Heute sind die Niederlande der größte Tulpenexporteur der Welt.`}],verdict:`umstritten`,why:`Die Preisspitze war echt, der wirtschaftliche Zusammenbruch weitgehend Legende.`,summary:[`1637: Preissturz in wenigen Tagen.`,`Archive zeigen kaum Pleiten.`,`Die Legende stammt aus Flugschriften und Mackay (1841).`],sources:[`Goldgar 2007, Tulipmania`]},{id:`kobra-effekt`,area:`WIRT`,day:42,hook:`Kann eine Belohnung alles schlimmer machen?`,mood:`raetsel`,images:[t(`kobra`)],slides:[{text:`Der **Kobra-Effekt**: Im britisch regierten Delhi soll es Kopfgeld für tote Kobras gegeben haben. Die Leute züchteten Kobras. Als die Prämie wegfiel, ließen sie sie frei – mehr Schlangen als vorher.`},{text:`Für Delhi gibt es dafür keinen **Beleg** aus der Zeit. Gut dokumentiert ist aber Hanoi 1902: Die französische Verwaltung zahlte für jeden Rattenschwanz. Bald liefen Ratten ohne Schwanz herum – man ließ sie zur Zucht leben.`,cam:[45,30,1.4]},{text:`Ökonomen nennen das **Fehlanreiz**: Belohnt man eine Messgröße, optimieren die Leute die Messgröße statt das Ziel. Das Goodhart’sche Gesetz: Wird ein Maß zum Ziel, taugt es nicht mehr als Maß.`}],verdict:`umstritten`,why:`Die Kobra-Geschichte ist nicht belegt, das Prinzip schon – etwa durch die Rattenjagd in Hanoi.`,summary:[`Kobras in Delhi: Anekdote ohne Beleg.`,`Rattenschwänze in Hanoi 1902: dokumentiert.`,`Goodhart: Ein Maß als Ziel verliert seinen Wert.`],sources:[`Vann 2003, French Colonial History`,`Goodhart 1975`]},{id:`geld-glueck`,area:`WIRT`,day:80,hook:`Macht Geld glücklich?`,mood:`hell`,images:[t(`euro`)],slides:[{text:`2010 meldeten Daniel Kahneman und Angus Deaton: Ab etwa **75.000 Dollar** Jahreseinkommen steigt die Tagesstimmung nicht mehr. Die Zahl wurde weltberühmt.`},{text:`2021 fand Matthew Killingsworth mit über 30.000 Menschen per Handy-Befragung: Das Wohlbefinden steigt **weiter** mit dem Einkommen. Wer hatte recht?`,cam:[50,50,1.35]},{text:`2023 werteten beide Seiten **gemeinsam** neu aus: Für die meisten steigt das Glück mit mehr Geld weiter – nur bei den Unglücklichsten flacht es ab. Und jeder zusätzliche Euro zählt umso weniger, je mehr man schon hat.`}],verdict:`belegt`,why:`Mehr Einkommen hängt mit mehr Wohlbefinden zusammen – mit abnehmendem Zuwachs.`,summary:[`2010: Grenze bei 75.000 $ – inzwischen überholt.`,`2023 gemeinsame Studie: meist kein Plateau.`,`Jeder weitere Euro bringt weniger.`],sources:[`Kahneman & Deaton 2010, PNAS`,`Killingsworth, Kahneman & Mellers 2023, PNAS`]},{id:`neun-neunzig`,area:`WIRT`,day:11,hook:`Warum kostet alles 9,99?`,mood:`verspielt`,ambience:`stadt`,images:[t(`preisschilder`)],slides:[{text:`Wir lesen Preise von **links nach rechts** – und die erste Ziffer bleibt hängen. 9,99 € fühlt sich nach „neun-irgendwas“ an, obwohl es praktisch zehn Euro sind.`},{text:`Studien bestätigen den **Linke-Ziffer-Effekt**: 2,99 wird deutlich günstiger eingeschätzt als 3,00 – der Unterschied zwischen 2,00 und 2,01 fällt dagegen kaum auf.`,cam:[50,45,1.4]},{text:`Luxusmarken meiden die 9 oft **bewusst**: Runde Preise wirken hochwertiger. Und die beliebte Erklärung, die krummen Preise sollten Diebstahl an der Kasse verhindern, ist kaum belegt.`}],verdict:`belegt`,why:`Der Linke-Ziffer-Effekt ist in Experimenten und Verkaufsdaten gut nachgewiesen.`,summary:[`Die erste Ziffer prägt das Preisgefühl.`,`2,99 wirkt viel billiger als 3,00.`,`Luxusmarken bevorzugen runde Preise.`],sources:[`Thomas & Morwitz 2005, Journal of Consumer Research`,`Anderson & Simester 2003, Quantitative Marketing and Economics`]}],r=[{id:`achillesferse`,area:`LIT`,day:20,hook:`Steht die Achillesferse bei Homer?`,mood:`episch`,images:[t(`laeufer`)],slides:[{text:`Achilles ist der größte Held der **Ilias**: Er tötet Hektor vor Troja. Doch Homer erwähnt nirgends eine verwundbare Ferse – und Achilles’ Tod kommt in der Ilias gar nicht vor.`},{text:`Die Geschichte vom **Bad im Styx** – seine Mutter Thetis taucht das Baby in den Unterweltfluss, nur die Ferse, an der sie es hält, bleibt trocken – steht erst beim römischen Dichter Statius, rund 800 Jahre nach Homer.`,cam:[45,70,1.4]},{text:`Heute heißt jede **Schwachstelle** Achillesferse. Und die Sehne über deiner Ferse heißt Achillessehne – sie ist die kräftigste Sehne im ganzen Körper.`}],verdict:`hype`,why:`Die verwundbare Ferse kommt bei Homer nicht vor – sie ist eine viel spätere Ergänzung.`,summary:[`Ilias: keine Ferse, kein Tod des Achilles.`,`Das Styx-Bad erst bei Statius (1. Jh. n. Chr.).`,`Achillessehne: kräftigste Sehne des Körpers.`],sources:[`Statius, Achilleis I`,`Homer, Ilias`]},{id:`shakespeare-woerter`,area:`LIT`,day:59,hook:`Hat Shakespeare 1.700 Wörter erfunden?`,mood:`verspielt`,images:[t(`globe-theatre`)],slides:[{text:`Die Zahl kursiert überall: Shakespeare habe die englische Sprache um rund **1.700 Wörter** bereichert – „lonely“, „swagger“ oder „eyeball“ etwa.`},{text:`Das Problem: Das große Oxford-Wörterbuch nannte lange einfach die **früheste gedruckte** Stelle, die man kannte – und Shakespeare wurde besonders gründlich gelesen. In digitalisierten Texten tauchen viele seiner „Erfindungen“ nun bei älteren Autoren auf.`,cam:[50,45,1.3]},{text:`Was bleibt, ist beeindruckend genug: Wendungen wie **„green-eyed monster“** für Eifersucht gehen auf ihn zurück. Und „Sein oder Nichtsein“ zitiert auch im Deutschen jeder – aus Hamlet.`}],verdict:`umstritten`,why:`Viele Wörter sind bei ihm nur zum ersten Mal gedruckt belegt. Erfunden hat er deutlich weniger.`,summary:[`Die 1.700-Wörter-Zahl beruht auf Erstbelegen.`,`Digitale Archive finden ältere Belege.`,`„Green-eyed monster“ geht auf ihn zurück.`],sources:[`Oxford English Dictionary`,`Folger Shakespeare Library`]},{id:`sisyphos`,area:`LIT`,day:20,hook:`Macht sinnlose Arbeit unglücklich?`,mood:`dunkel`,images:[t(`lego`)],slides:[{text:`Zur Strafe muss **Sisyphos** in der Unterwelt einen Felsen bergauf rollen – kurz vor dem Gipfel rollt er wieder hinab. Für immer. Die Griechen erfanden damit das Bild der sinnlosen Mühe.`},{text:`Der Verhaltensökonom Dan Ariely testete das 2008: Studierende bauten **Lego-Figuren** gegen Geld. Bei einer Gruppe wurden die fertigen Figuren vor ihren Augen wieder zerlegt. Diese Gruppe hörte viel früher auf – bei gleichem Lohn.`,cam:[45,50,1.35]},{text:`Albert Camus deutete Sisyphos 1942 anders: Wer die Sinnlosigkeit erkennt und trotzdem weitermacht, ist frei. Sein Schluss: **„Wir müssen uns Sisyphos als einen glücklichen Menschen vorstellen.“**`}],verdict:`belegt`,why:`Experimente zeigen: Wer den Sinn seiner Arbeit nicht sieht, gibt schneller auf – auch bei gleicher Bezahlung.`,summary:[`Sisyphos: ewige, sinnlose Mühe.`,`Lego-Experiment: Sinn hält länger bei der Arbeit.`,`Camus: Sisyphos als glücklicher Mensch.`],sources:[`Ariely, Kamenica & Prelec 2008, J Econ Behav Organ`,`Camus 1942, Der Mythos des Sisyphos`]},{id:`grimm`,area:`LIT`,day:48,hook:`Waren Grimms Märchen früher grausamer?`,mood:`raetsel`,ambience:`nacht`,images:[t(`maerchenwald`)],slides:[{text:`1812 erschien die erste Ausgabe der **Kinder- und Hausmärchen**. Die Brüder Grimm wollten Volkspoesie bewahren – das Buch richtete sich eher an Gelehrte als an Kinder.`},{text:`Spätere Ausgaben wurden kindgerechter, vor allem beim Thema **Sexualität**: Rapunzel verrät sich 1812, weil ihre Kleider zu eng werden – sie ist schwanger. Später fragt sie nur noch, warum die Hexe schwerer heraufzuziehen ist als der Prinz.`,cam:[50,55,1.3]},{text:`Bei der Gewalt war es umgekehrt: In Aschenputtel hacken sich die Stiefschwestern schon 1812 Zehe und Ferse ab – ab 1819 picken ihnen zusätzlich **Tauben die Augen** aus. Wilhelm Grimm fügte Strafen eher hinzu.`}],verdict:`umstritten`,why:`Sexuelles wurde entschärft, Gewalt teils sogar verstärkt. „Früher grausamer“ stimmt nur halb.`,summary:[`Erste Ausgabe 1812, eher für Erwachsene.`,`Entschärft: Rapunzels Schwangerschaft.`,`Verschärft: Tauben picken ab 1819 Augen aus.`],sources:[`Grimm, Kinder- und Hausmärchen, Ausgaben 1812 und 1819`,`Tatar 2003, The Hard Facts of the Grimms’ Fairy Tales`]},{id:`mona-lisa`,area:`KUL`,day:13,hook:`Folgen dir Mona Lisas Augen durch den Raum?`,mood:`raetsel`,ambience:`stadt`,images:[t(`mona-lisa-louvre`)],slides:[{text:`Das behaupten Reiseführer seit Generationen, der Effekt heißt sogar **Mona-Lisa-Effekt**: Ein gemaltes Gesicht scheint dich anzusehen, egal wo du stehst.`},{text:`2019 prüften Forscher der Uni Bielefeld das bei der Mona Lisa selbst. Ergebnis: Sie schaut gar nicht dich an, sondern etwa **15 Grad** rechts an dir vorbei.`,cam:[50,35,1.5]},{text:`Den Effekt gibt es trotzdem – bei Porträts, die **frontal** aus dem Bild blicken: Ein Bild ist flach, der Blick ändert sich nicht, wenn du dich bewegst. Und die Mona Lisa ist nur 77 mal 53 Zentimeter groß.`}],verdict:`hype`,why:`Der Effekt ist echt – aber ausgerechnet die Mona Lisa zeigt ihn nicht.`,summary:[`Frontal blickende Porträts „folgen“ dir.`,`Die Mona Lisa schaut 15° an dir vorbei.`,`77 × 53 cm – kleiner als gedacht.`],sources:[`Horstmann & Loth 2019, i-Perception`,`Musée du Louvre`]},{id:`van-gogh-ohr`,area:`KUL`,day:60,hook:`Schnitt sich Van Gogh nur ein Ohrläppchen ab?`,mood:`dunkel`,images:[t(`sonnenblumen`)],slides:[{text:`Arles, 23. Dezember 1888: Nach einem Streit mit Paul Gauguin verletzt sich Vincent van Gogh mit einem **Rasiermesser** am linken Ohr. Lange hieß es: nur ein Stück vom Ohrläppchen.`},{text:`2016 fand die Forscherin Bernadette Murphy eine **Skizze** des behandelnden Arztes Félix Rey. Sie zeigt: Van Gogh schnitt fast das ganze Ohr ab.`,cam:[50,40,1.35]},{text:`Wenige Wochen später malte er sich mit **Verband** – im Spiegel, deshalb sitzt er auf dem Bild rechts. Zu Lebzeiten verkaufte Van Gogh kaum Bilder, heute zählen seine Sonnenblumen zu den teuersten Gemälden der Welt.`}],verdict:`belegt`,why:`Die Arztskizze von 1889 zeigt: Fast das ganze linke Ohr fehlte.`,summary:[`23. Dezember 1888, Arles, nach Streit mit Gauguin.`,`Die Arztskizze belegt: fast das ganze Ohr.`,`Im Spiegel gemalt – deshalb Verband rechts.`],sources:[`Murphy 2016, Van Gogh’s Ear`,`Van Gogh Museum Amsterdam`]},{id:`mozart-effekt`,area:`KUL`,day:51,hook:`Macht Mozart hören klüger?`,mood:`hell`,images:[t(`geige`)],slides:[{text:`1993 berichtete die Zeitschrift Nature: Studierende lösten nach zehn Minuten **Mozart-Sonate** räumliche Aufgaben besser. Daraus wurde der „Mozart-Effekt“ – der US-Bundesstaat Georgia verschenkte sogar Klassik-CDs an Neugeborene.`},{text:`Der Effekt hielt nur etwa **15 Minuten** und betraf nur räumliches Vorstellen. Spätere Versuche zeigten: Jede Musik, die munter macht, wirkt ähnlich – sogar eine spannende Geschichte.`,cam:[50,45,1.4]},{text:`Eine große Auswertung der Uni Wien 2010 mit rund 3.000 Teilnehmenden fand **keinen** besonderen Effekt. Wer selbst ein Instrument lernt, schneidet in manchen Tests besser ab – ob das die Ursache ist, ist strittig.`}],verdict:`hype`,why:`Nur ein kurzer Wachmacher-Effekt, nicht typisch für Mozart – und keine dauerhafte Intelligenz.`,summary:[`1993: kurzer Effekt auf räumliches Denken.`,`Muntermachende Musik wirkt ähnlich.`,`Meta-Analyse 2010: kein Mozart-Effekt.`],sources:[`Rauscher, Shaw & Ky 1993, Nature`,`Pietschnig, Voracek & Formann 2010, Intelligence`]},{id:`nachtwache`,area:`KUL`,day:13,hook:`Spielt die Nachtwache bei Nacht?`,mood:`episch`,ambience:`stadt`,images:[t(`rijksmuseum`)],slides:[{text:`Rembrandts berühmtestes Bild heißt **Nachtwache** – dabei zeigt es eine Bürgerwehr bei Tag. Der Name kam erst gegen Ende des 18. Jahrhunderts auf.`},{text:`Der Grund: Schichten aus **Firnis** und Schmutz dunkelten das Bild über Jahrhunderte nach. Erst Reinigungen zeigten, wie viel Licht Rembrandt eigentlich gemalt hatte.`,cam:[50,45,1.35]},{text:`Das Bild wurde außerdem **beschnitten**: 1715 zog es ins Amsterdamer Rathaus und passte nicht an die Wand – also schnitt man Streifen ab, links am meisten. 2021 ergänzte das Rijksmuseum die fehlenden Teile mithilfe von KI.`}],verdict:`hype`,why:`Eine Tagesszene, nachgedunkelt durch alten Firnis. Der Titel ist ein Missverständnis.`,summary:[`Eigentlich eine Szene bei Tageslicht.`,`Alter Firnis dunkelte das Bild nach.`,`1715 beschnitten, 2021 per KI ergänzt.`],sources:[`Rijksmuseum Amsterdam: Operation Night Watch`]}],i=[{id:`schlafposition`,area:`PSY`,day:16,hook:`Verrät deine Schlafposition, wer du bist?`,mood:`ruhig`,ambience:`atem`,images:[t(`hund-schlaf`)],slides:[{text:`Embryo, Soldat, Freifaller: Seit 2003 geistert eine Liste durchs Netz, nach der jede **Schlafposition** zu einem Charakter passt. Zusammengerollt heißt angeblich: harte Schale, weicher Kern.`},{text:`Die Quelle: eine **Umfrage** unter rund 1.000 Briten, ausgewertet vom Schlafforscher Chris Idzikowski. Die Leute schätzten Haltung und Charakter selbst ein – kein Persönlichkeitstest, nie wissenschaftlich veröffentlicht.`,cam:[45,40,1.35]},{text:`Belegt ist anderes: Man wechselt die Haltung nachts **viele Male**. In Rückenlage schnarcht man mehr, und Schlafparalyse – wach, aber bewegungsunfähig – tritt dort am häufigsten auf.`}],verdict:`hype`,why:`Selbstauskunft von 1.000 Leuten, nie begutachtet. Über den Charakter verrät die Haltung nach heutigem Stand nichts.`,summary:[`Die Schlafpositions-Typen stammen aus einer Umfrage von 2003.`,`Nachts wechselt man die Haltung viele Male.`,`Rückenlage: mehr Schnarchen, häufiger Schlafparalyse.`],sources:[`BBC News 2003: „Sleep position gives personality clue“`,`Cheyne 2002, Journal of Sleep Research`]},{id:`gaehnen`,area:`PSY`,day:41,hook:`Warum steckt Gähnen an – sogar beim Lesen?`,mood:`verspielt`,images:[t(`baby-gaehnt`)],slides:[{text:`Oft reicht schon das Wort **Gähnen**: Rund die Hälfte der Erwachsenen gähnt mit, wenn sie andere gähnen sieht – manche sogar, wenn sie nur davon lesen.`},{text:`Lange galt das als Zeichen von **Mitgefühl**: Wer sich einfühlt, gähnt mit. Große Studien finden diesen Zusammenhang aber kaum – das Alter erklärt mehr: Je älter, desto seltener steckt Gähnen an.`,cam:[55,50,1.4]},{text:`Auch Schimpansen und sogar **Wellensittiche** lassen sich anstecken. Kleinkinder dagegen erst ab etwa vier Jahren. Warum wir überhaupt gähnen, ist offen – eine Idee: Es kühlt das Gehirn.`}],verdict:`umstritten`,why:`Ansteckendes Gähnen ist gut belegt. Dass es Mitgefühl misst, ist umstritten.`,summary:[`Rund die Hälfte der Erwachsenen gähnt mit.`,`Mitgefühl als Grund: umstritten, das Alter zählt mehr.`,`Auch Tiere stecken sich an, Kinder erst ab etwa vier.`],sources:[`Provine 2005, American Scientist`,`Bartholomew & Cirulli 2014, PLOS ONE`,`Gallup et al. 2015, Animal Cognition`]},{id:`dunning-kruger`,area:`PSY`,day:63,hook:`Wer wenig weiß, hält sich für ein Genie?`,mood:`raetsel`,images:[t(`schach`)],slides:[{text:`1999 testeten David Dunning und Justin Kruger Studierende in Logik und Grammatik. Die Schwächsten landeten im Schnitt auf Platz 12 von 100 – und schätzten sich auf Platz **62**.`},{text:`Daraus wurde ein Meme: eine Kurve mit „Gipfel des Unwissens“. Die stammt aber nicht aus der Studie. Und ein Teil des Effekts ist **Statistik**: Wer ganz unten liegt, kann sich fast nur überschätzen.`,cam:[40,50,1.35]},{text:`Was bleibt: Wer etwas nicht kann, erkennt Fehler schlechter – dafür fehlt genau das Wissen. Gute Nachricht aus derselben Studie: Schon kurzes **Üben** verbesserte Können und Selbsteinschätzung.`}],verdict:`umstritten`,why:`Selbstüberschätzung bei Anfängern gibt es. Wie groß der Effekt wirklich ist, ist strittig – ein Teil ist ein Rechenartefakt.`,summary:[`Die Schwächsten schätzten sich auf Platz 62 statt 12.`,`Die berühmte Kurve stammt nicht aus der Studie.`,`Üben verbessert Können und Selbsteinschätzung.`],sources:[`Kruger & Dunning 1999, J Pers Soc Psychol`,`Gignac & Zajenkowski 2020, Intelligence`]},{id:`marshmallow`,area:`PSY`,day:55,hook:`Sagt ein Marshmallow deine Zukunft voraus?`,mood:`verspielt`,images:[t(`marshmallows`)],slides:[{text:`In den 1960ern ließ Walter Mischel Kinder wählen: ein **Marshmallow** sofort – oder zwei, wenn sie rund 15 Minuten allein warten.`},{text:`Jahre später schienen die Warter erfolgreicher: bessere Noten, bessere Testwerte. Die Folgerung: **Selbstkontrolle** entscheidet über das Leben.`,cam:[50,50,1.4]},{text:`2018 wiederholten Forscher den Test mit über 900 Kindern aus allen Schichten. Der Effekt schrumpfte stark – und fast ganz, sobald man **Familie und Umfeld** einrechnete. Warten heißt auch: Ich vertraue darauf, dass das Versprechen gilt.`}],verdict:`umstritten`,why:`Der Zusammenhang existiert, ist aber viel kleiner als gedacht. Herkunft und Vertrauen erklären einen großen Teil.`,summary:[`Original: wenige Kinder einer Uni-Kita.`,`2018 mit über 900 Kindern: Effekt viel kleiner.`,`Warten hängt auch von Vertrauen und Umfeld ab.`],sources:[`Mischel, Shoda & Rodriguez 1989, Science`,`Watts, Duncan & Quan 2018, Psychological Science`,`Kidd, Palmeri & Aslin 2013, Cognition`]},{id:`sokrates`,area:`PHIL`,day:22,hook:`„Ich weiß, dass ich nichts weiß“ – hat Sokrates das gesagt?`,mood:`ruhig`,images:[t(`sokrates-buste`)],slides:[{text:`Sokrates schrieb selbst nichts. Was wir über ihn wissen, stammt vor allem von seinem Schüler **Platon**. In dessen „Apologie“ verteidigt sich Sokrates vor Gericht.`},{text:`Dort sagt er sinngemäß: Ich bin weiser als andere, weil ich nicht **glaube**, etwas zu wissen, was ich nicht weiß. Das ist feiner als der berühmte Satz – Ehrlichkeit über die Grenzen des eigenen Wissens.`,cam:[50,35,1.35]},{text:`399 v. Chr. wurde er wegen „Verderbens der Jugend“ zum Tod verurteilt und trank den **Schierlingsbecher**. Fliehen wollte er nicht – er hielt sich an die Gesetze seiner Stadt.`}],verdict:`umstritten`,why:`Die knappe Formel steht so nicht bei Platon. Der Gedanke dahinter schon.`,summary:[`Sokrates schrieb nichts, Platon überliefert ihn.`,`Original: Ich glaube nicht zu wissen, was ich nicht weiß.`,`399 v. Chr. zum Tod verurteilt.`],sources:[`Platon, Apologie 21d`,`Platon, Kriton`]},{id:`diogenes`,area:`PHIL`,day:22,hook:`Lebte Diogenes wirklich in einer Tonne?`,mood:`verspielt`,ambience:`stadt`,images:[t(`pithoi-knossos`)],slides:[{text:`Diogenes von Sinope wollte im 4. Jahrhundert v. Chr. zeigen: Man braucht fast nichts zum Glück. Er schlief in Athen in einem **Pithos** – einem großen Vorratsgefäß aus Ton wie diesen, keinem Holzfass.`},{text:`Berühmte Anekdote: Alexander der Große besucht ihn und bietet ihm einen Wunsch. Diogenes: „**Geh mir aus der Sonne.**“ Alexander soll gesagt haben: Wäre ich nicht Alexander, wollte ich Diogenes sein.`,cam:[40,50,1.35]},{text:`Seine Schule hieß **Kyniker** – von „kyon“, Hund, weil sie so bedürfnislos lebten wie Straßenhunde. Daraus wurde unser Wort „zynisch“.`}],verdict:`umstritten`,why:`Der Tonkrug ist gut überliefert, viele Anekdoten stammen aber erst aus Quellen Jahrhunderte später.`,summary:[`Pithos = Tonkrug, kein Holzfass.`,`„Geh mir aus der Sonne“ – zu Alexander.`,`Kyniker → zynisch, von griechisch „Hund“.`],sources:[`Diogenes Laertios, Leben und Meinungen berühmter Philosophen, Buch VI`]},{id:`weiche`,area:`PHIL`,day:46,hook:`Würdest du die Weiche umstellen?`,mood:`dunkel`,images:[t(`weiche`)],slides:[{text:`Ein Zug rast auf fünf Menschen zu. Stellst du die **Weiche** um, stirbt stattdessen einer auf dem Nebengleis. Das Gedankenexperiment stammt von der Philosophin Philippa Foot, 1967.`},{text:`Die meisten sagen: umstellen – fünf retten ist besser als einen. Das denkt **utilitaristisch**. Aber würdest du einen Mann von einer Brücke stoßen, um den Zug zu stoppen? Da sagen die meisten nein, obwohl die Rechnung gleich ist.`,cam:[40,55,1.35]},{text:`Eine Studie mit 70.000 Menschen aus 42 Ländern fand: Die Weiche umstellen würden rund **80 Prozent**, den Mann stoßen nur etwa ein Drittel – in allen Kulturen dieselbe Reihenfolge.`}],verdict:`belegt`,why:`Die Reaktionen sind weltweit gut untersucht: Weiche ja, Stoßen meist nein – quer durch die Kulturen.`,summary:[`Philippa Foot, 1967.`,`Weiche: rund 80 % ja, Brücke: etwa ein Drittel.`,`Handeln oder geschehen lassen – Kern der Ethikdebatte.`],sources:[`Foot 1967, Oxford Review`,`Awad et al. 2020, PNAS`]},{id:`stoiker`,area:`PHIL`,day:85,hook:`Sind Stoiker Menschen ohne Gefühle?`,mood:`ruhig`,ambience:`uhr`,images:[t(`marc-aurel`),t(`sanduhr`)],slides:[{text:`„Stoisch“ heißt heute: ungerührt. Die antiken **Stoiker** – Seneca, Epiktet, Kaiser Marc Aurel – wollten aber keine Gefühllosigkeit, sondern Freiheit von zerstörerischen Leidenschaften wie Wut und Panik.`},{text:`Ihr Kern: Unterscheide, was in deiner **Macht** liegt – dein Urteil, dein Handeln – und was nicht. Epiktet: Nicht die Dinge beunruhigen uns, sondern unsere Meinungen über die Dinge.`,cam:[45,30,1.4]},{text:`Genau dieser Gedanke inspirierte im 20. Jahrhundert die **kognitive Verhaltenstherapie**: Albert Ellis und Aaron Beck beriefen sich auf die Stoa. Und „Memento mori“ hieß für sie: Nutze die Zeit.`,img:1}],verdict:`hype`,why:`Die Stoiker schätzten gute Gefühle wie Freude. Ihre Methode wirkt in der heutigen Therapie weiter.`,summary:[`Ziel: Freiheit von Wut und Panik, nicht von Gefühlen.`,`Trenne, was du ändern kannst, von dem, was nicht.`,`Vorbild der kognitiven Verhaltenstherapie.`],sources:[`Epiktet, Handbüchlein der Moral 5`,`Robertson 2019, The Philosophy of Cognitive-Behavioural Therapy`]},{id:`goldfisch`,area:`DENK`,day:6,hook:`Haben Goldfische ein Drei-Sekunden-Gedächtnis?`,mood:`verspielt`,ambience:`blasen`,images:[t(`goldfisch`)],slides:[{text:`Der Mythos ist praktisch: Der Fisch dreht seine Runde, und alles ist neu. Nur stimmt er nicht. Goldfische können sich Dinge **monatelang** merken.`},{text:`In Versuchen lernten Goldfische, für Futter einen **Hebel** zu drücken – sogar nur zu einer bestimmten Tageszeit. Andere unterschieden Farben und Töne oder fanden den Weg durch kleine Labyrinthe.`,cam:[40,45,1.4]},{text:`Und du? Dein Arbeitsgedächtnis hält nur rund **vier** Dinge gleichzeitig. Was bleiben soll, musst du abrufen und wiederholen – genau dafür gibt es die Karteikarten in dieser App.`}],verdict:`hype`,why:`Experimente zeigen Erinnerungen über Wochen bis Monate.`,summary:[`Goldfische erinnern sich monatelang.`,`Sie lernen sogar Fütterungszeiten.`,`Menschliches Arbeitsgedächtnis: etwa vier Einheiten.`],sources:[`Gee, Stephenson & Wright 1994, J Exp Anal Behav`,`Cowan 2001, Behavioral and Brain Sciences`]},{id:`lerntypen`,area:`DENK`,day:6,hook:`Bist du ein visueller Lerntyp?`,mood:`ruhig`,images:[t(`bibliothek`)],slides:[{text:`Visuell, auditiv, haptisch: Viele haben in der Schule einen **Lerntyp-Test** gemacht. Die Idee: Wer im passenden Stil lernt, lernt besser.`},{text:`2008 prüften Harold Pashler und Kollegen die Forschung. Kaum eine Studie testete das sauber – und die guten fanden **keinen Vorteil**, wenn der Unterricht zum Lerntyp passt. Vorlieben gibt es, einen Lerneffekt nicht.`,cam:[50,55,1.35]},{text:`Was wirklich hilft, gilt für fast alle: **Abrufen** statt nur durchlesen, in Abständen lernen, Bild und Wort verbinden. Das Thema bestimmt die Form – Geografie lernt jeder besser mit Karte.`}],verdict:`hype`,why:`Unterricht nach Lerntyp bringt nachweislich nichts. Abrufen und verteiltes Lernen wirken bei allen.`,summary:[`Lernvorlieben gibt es, Lerntyp-Effekte nicht.`,`Pashler et al. 2008: kein Beleg.`,`Für alle wirksam: Abrufen, Abstände, Bild + Wort.`],sources:[`Pashler et al. 2008, Psychological Science in the Public Interest`,`Dunlosky et al. 2013, PSPI`]},{id:`stoerche`,area:`DENK`,day:54,hook:`Bringt der Storch die Babys?`,mood:`hell`,ambience:`wind`,images:[t(`storch`)],slides:[{text:`Der Statistiker Robert Matthews zeigte im Jahr 2000 augenzwinkernd: In 17 europäischen Ländern hängen die Zahl der **Storchenpaare** und die Zahl der Geburten tatsächlich zusammen.`},{text:`Der Trick: Große Länder haben mehr Fläche, mehr Störche und mehr Menschen – also auch mehr Geburten. Eine **dritte Größe** steckt hinter beidem. Korrelation heißt nicht Kausalität.`,cam:[45,45,1.35]},{text:`Solche **Scheinkorrelationen** sind überall: Eisverkauf und Sonnenbrand steigen gemeinsam – wegen des Sommers. Wer immer fragt „Was könnte beides verursachen?“, fällt seltener herein.`}],verdict:`hype`,why:`Die Korrelation ist echt, der Storch als Ursache natürlich nicht – dahinter steckt die Landesgröße.`,summary:[`Störche und Geburten korrelieren in Europa.`,`Dahinter steckt eine dritte Größe: die Landesgröße.`,`Immer fragen: Was verursacht beides?`],sources:[`Matthews 2000, Teaching Statistics`]},{id:`ziegenproblem`,area:`DENK`,day:25,hook:`Drei Türen, ein Auto: Solltest du wechseln?`,mood:`raetsel`,images:[t(`ziege`)],slides:[{text:`Hinter einer von drei Türen steht ein Auto, hinter den anderen **Ziegen**. Du wählst Tür 1. Der Moderator, der alles weiß, öffnet Tür 3 – eine Ziege. Wechselst du zu Tür 2?`},{text:`Fast alle sagen: egal, jetzt 50 zu 50. Falsch – **Wechseln** gewinnt in zwei von drei Fällen. Deine erste Wahl trifft nur mit einem Drittel. Die übrigen zwei Drittel liegen jetzt auf der Tür, die der Moderator stehen lässt.`,cam:[50,40,1.35]},{text:`1990 erklärte Marilyn vos Savant das in einer Zeitschrift – und bekam Tausende **Protestbriefe**, auch von Mathematikern. Sogar der berühmte Paul Erdős glaubte es erst nach einer Computersimulation.`}],verdict:`belegt`,why:`Rechnung und Simulation zeigen: Wechseln gewinnt in zwei Dritteln der Fälle.`,summary:[`Erste Wahl: 1/3 Chance.`,`Wechseln: 2/3 Chance.`,`Selbst Paul Erdős zweifelte.`],sources:[`vos Savant 1990, Parade Magazine`,`Vazsonyi 1999, Decision Line`]}],a=[{id:`bakterien`,area:`BIO`,day:53,hook:`Bist du mehr Bakterie als Mensch?`,mood:`raetsel`,ambience:`blasen`,images:[t(`e-coli`)],slides:[{text:`Jahrzehntelang hieß es: Auf jede Körperzelle kommen **zehn Bakterien**. Die Zahl stammt aus einer groben Schätzung von 1972 – und wurde danach einfach weiter abgeschrieben.`},{text:`2016 rechneten die Forscher Ron Sender, Shai Fuchs und Ron Milo neu: rund **38 Billionen** Bakterien gegen etwa 30 Billionen menschliche Zellen. Also ungefähr eins zu eins.`,cam:[40,45,1.5]},{text:`Die meisten deiner Zellen sind übrigens **rote Blutkörperchen** – rund 84 Prozent. Und das Verhältnis schwankt: Nach jedem Toilettengang verschiebt es sich Richtung Mensch.`}],verdict:`hype`,why:`Die „Zehn zu eins“-Zahl war eine Überschlagsrechnung. Heute geht man von etwa eins zu eins aus.`,summary:[`„Zehnmal mehr Bakterien“ stammt aus einer Schätzung von 1972.`,`Neu gerechnet: etwa 38 zu 30 Billionen.`,`84 Prozent deiner Zellen sind rote Blutkörperchen.`],sources:[`Sender, Fuchs & Milo 2016, PLOS Biology`,`Luckey 1972, Am J Clin Nutr`]},{id:`giraffenhals`,area:`BIO`,day:10,hook:`Wurde der Giraffenhals lang, weil sie sich streckten?`,mood:`hell`,ambience:`wind`,images:[t(`giraffen-necking`)],slides:[{text:`So erklärte es Jean-Baptiste Lamarck um 1809: Giraffen recken sich nach Blättern, der Hals wird länger – und das **Erworbene** erben die Jungen.`},{text:`Darwin sah es anders: Unter vielen Giraffen haben manche zufällig etwas längere Hälse. Die kommen in Dürren besser an Futter und bekommen mehr Junge. Das ist **Selektion** – über viele Generationen.`,cam:[35,30,1.4]},{text:`Dazu kommt das **Necking**: Giraffenbullen kämpfen mit ihren Hälsen, längere gewinnen öfter. Und trotz zwei Metern Hals haben Giraffen nur sieben Halswirbel – genau wie du.`,cam:[50,35,1.25]}],verdict:`belegt`,why:`Vererbung erworbener Eigenschaften ist widerlegt, Selektion belegt. Ob Futter oder Kämpfe den Hals formten, wird noch diskutiert.`,summary:[`Lamarck: Strecken wird vererbt – widerlegt.`,`Darwin: zufällige Unterschiede + Selektion.`,`Giraffen haben nur sieben Halswirbel.`],sources:[`Simmons & Scheepers 1996, American Naturalist`,`Darwin 1872, On the Origin of Species, 6. Aufl.`]},{id:`zehn-prozent`,area:`BIO`,day:86,hook:`Nutzt du nur zehn Prozent deines Gehirns?`,mood:`kosmisch`,images:[t(`mrt-gehirn`)],slides:[{text:`Filme wie „Lucy“ leben von der Idee: Würden wir die restlichen 90 Prozent **freischalten**, hätten wir Superkräfte. Eine wissenschaftliche Quelle für die Zahl gibt es nicht.`},{text:`Hirnscans zeigen: Über den Tag sind praktisch **alle Bereiche** aktiv, nur nicht alle gleichzeitig. Schon kleine Schäden – etwa nach einem Schlaganfall – haben spürbare Folgen.`,cam:[50,50,1.35]},{text:`Und das Gehirn ist teuer: Es macht rund **2 Prozent** des Körpergewichts aus, verbraucht aber etwa 20 Prozent der Energie. Ein nutzloses Organ dieser Größe hätte die Evolution nicht durchgehen lassen.`}],verdict:`hype`,why:`Hirnscans und Hirnverletzungen zeigen: Es gibt keinen stillen, ungenutzten Großteil.`,summary:[`Die 10-Prozent-Zahl hat keine wissenschaftliche Quelle.`,`Im Tagesverlauf sind fast alle Areale aktiv.`,`2 % Körpergewicht, 20 % der Energie.`],sources:[`Beyerstein 1999, in: Mind Myths (Wiley)`,`Raichle & Gusnard 2002, PNAS`]},{id:`spinat`,area:`BIO`,day:65,hook:`Macht Spinat wirklich stark?`,mood:`verspielt`,images:[t(`spinat`)],slides:[{text:`Popeye isst Spinat und wird zum Kraftprotz. Der Grund laut Legende: Ein Forscher setzte ein **Komma** falsch, und Spinat hatte plötzlich zehnmal so viel Eisen.`},{text:`Die Pointe: Auch die Komma-Geschichte ist ein **Mythos** – der Kriminologe Mike Sutton fand dafür keinen Beleg. Spinat hat rund 3 mg Eisen pro 100 Gramm: ordentlich, aber kein Rekord.`,cam:[40,40,1.4]},{text:`**Oxalsäure** im Spinat bindet einen Teil davon, der Körper kommt schlecht ran. Vitamin C – etwa aus Paprika – hilft. Und Popeye aß Spinat in einem Comic von 1932 wegen Vitamin A, nicht wegen Eisen.`}],verdict:`hype`,why:`Spinat ist gesund, aber keine Eisen-Bombe – und sogar die berühmte Komma-Erklärung ist erfunden.`,summary:[`Spinat: rund 3 mg Eisen pro 100 g.`,`Oxalsäure bremst die Aufnahme, Vitamin C hilft.`,`Die Komma-Legende ist selbst ein Mythos.`],sources:[`Sutton 2010, Internet Journal of Criminology`,`USDA FoodData Central: Spinach, raw`]},{id:`newton-apfel`,area:`PHY`,day:19,hook:`Fiel Newton wirklich ein Apfel auf den Kopf?`,mood:`hell`,images:[t(`newton-baum`),t(`apfelbaum`)],slides:[{text:`Die Geschichte ist fast wahr: Newton erzählte sie im Alter selbst seinem Freund William **Stukeley**. Um 1666 sah er im Garten von Woolsthorpe einen Apfel fallen.`},{text:`Auf den **Kopf** fiel er aber nicht – das ist eine spätere Ausschmückung. Newton fragte sich: Warum fällt der Apfel senkrecht? Und reicht dieselbe Kraft bis zum Mond?`,img:1},{text:`Daraus wurde das **Gravitationsgesetz**: Jede Masse zieht jede andere an, schwächer mit dem Quadrat der Entfernung. Der Apfelbaum steht übrigens noch heute in Woolsthorpe Manor.`,img:0}],verdict:`hype`,why:`Den fallenden Apfel beschrieb Newton selbst. Der Treffer auf den Kopf ist eine spätere Zutat.`,summary:[`Newton erzählte die Apfel-Geschichte selbst.`,`Vom Kopf ist bei ihm keine Rede.`,`Gleiche Kraft für Apfel und Mond: Gravitation.`],sources:[`Stukeley 1752, Memoirs of Sir Isaac Newton’s Life (Royal Society)`,`Newton 1687, Principia`]},{id:`blitz`,area:`PHY`,day:37,hook:`Schlägt der Blitz nie zweimal ein?`,mood:`episch`,ambience:`regen`,images:[t(`blitz-eiffelturm`)],cam:[50,30,1.1],slides:[{text:`Das Sprichwort ist gründlich falsch: Das **Empire State Building** wird im Schnitt 20- bis 25-mal pro Jahr getroffen. Dieses Foto zeigt den Eiffelturm, 1902.`},{text:`Blitze nehmen den Weg des geringsten Widerstands – oft über **hohe, spitze** Punkte. Was einmal getroffen wurde, steht ja immer noch dort. Dafür gibt es Blitzableiter, erfunden von Benjamin Franklin um 1750.`,cam:[50,20,1.5]},{text:`Ein Blitz ist bis zu **30.000 Grad** heiß – fünfmal heißer als die Sonnenoberfläche. Donner ist die explodierende Luft. Sekunden zwischen Blitz und Donner geteilt durch drei: Entfernung in Kilometern.`,cam:[50,60,1.2]}],verdict:`hype`,why:`Blitze treffen bevorzugt hohe Punkte – immer wieder dieselben.`,summary:[`Empire State Building: rund 20–25 Treffer pro Jahr.`,`Hohe, spitze Punkte werden bevorzugt getroffen.`,`Sekunden bis zum Donner ÷ 3 = Kilometer.`],sources:[`NOAA National Weather Service: Lightning Myths`,`NOAA: How Hot Is Lightning?`]},{id:`tote-sterne`,area:`PHY`,day:84,hook:`Siehst du nachts Sterne, die längst tot sind?`,mood:`kosmisch`,ambience:`weltraum`,images:[t(`orion`)],slides:[{text:`Klingt poetisch: Das Licht ist so lange unterwegs, dass der Stern inzwischen **erloschen** sein könnte. Bei fernen Galaxien stimmt das Prinzip – ihr Licht ist Millionen Jahre alt.`},{text:`Aber die Sterne, die du mit bloßem Auge siehst, sind fast alle **in der Nähe**: meist wenige hundert bis tausend Lichtjahre. Sterne leben Millionen bis Milliarden Jahre – die Chance, dass einer schon tot ist, ist winzig.`,cam:[45,50,1.4]},{text:`Heißester Kandidat ist **Beteigeuze**, die rote Schulter des Orion, rund 550 Lichtjahre entfernt. Sie wird als Supernova explodieren – vermutlich aber erst in den nächsten 100.000 Jahren.`,cam:[40,25,1.6]}],verdict:`hype`,why:`Für Sterne am Nachthimmel fast immer falsch – sie sind zu nah und leben zu lange.`,summary:[`Sichtbare Sterne sind meist nur hunderte bis tausende Lichtjahre entfernt.`,`Sterne leben Millionen bis Milliarden Jahre.`,`Beteigeuze explodiert irgendwann – wohl nicht bald.`],sources:[`ESA: Hipparcos-Katalog`,`Joyce et al. 2020, Astrophysical Journal`]},{id:`gps-einstein`,area:`PHY`,day:49,hook:`Ohne Einstein würde dich dein Handy in die Irre führen.`,mood:`kosmisch`,ambience:`weltraum`,images:[t(`gps-satellit`)],slides:[{text:`GPS-Satelliten tragen **Atomuhren**. Dein Handy misst, wie lange ihre Signale brauchen, und berechnet daraus deinen Ort. Dafür muss die Zeit auf Milliardstel Sekunden stimmen.`},{text:`Doch die Uhren dort oben gehen anders: wegen ihres Tempos **langsamer**, wegen der schwächeren Schwerkraft **schneller** – das sind beide Relativitätstheorien. Unterm Strich rund 38 Mikrosekunden pro Tag zu schnell.`,cam:[55,40,1.4]},{text:`Klingt nach nichts – aber Licht legt in 38 Mikrosekunden über **11 Kilometer** zurück. Ohne Korrektur würde dein Standort jeden Tag um Kilometer abdriften. Relativität ist Alltagstechnik.`}],verdict:`belegt`,why:`Die Uhren werden genau um diesen Betrag korrigiert – sonst funktioniert GPS nicht.`,summary:[`GPS braucht Uhren, die auf Milliardstel genau gehen.`,`Netto gehen die Satellitenuhren 38 µs pro Tag vor.`,`Ohne Korrektur: Kilometer Fehler pro Tag.`],sources:[`Ashby 2003, Living Reviews in Relativity`]},{id:`gold-machen`,area:`CHE`,day:58,hook:`Kann man aus Blei Gold machen?`,mood:`raetsel`,ambience:`feuer`,images:[t(`goldbarren`)],slides:[{text:`Jahrhundertelang suchten **Alchemisten** danach. 1669 kochte Hennig Brand in Hamburg Urin ein – Gold fand er nicht, aber einen Stoff, der im Dunkeln leuchtete: Phosphor.`},{text:`Chemisch geht es nicht: Ein Element wird durch die Zahl der **Protonen** im Kern bestimmt – Gold hat 79, Blei 82. Chemische Reaktionen verschieben nur Elektronen, den Kern rühren sie nicht an.`,cam:[45,45,1.4]},{text:`**Kernphysik** schafft es: 1980 wandelten Forscher um Glenn Seaborg Bismut in winzige Mengen Gold um, 2025 meldete das CERN Gold aus Blei-Kollisionen. Kosten: weit mehr, als das Gold wert ist.`}],verdict:`belegt`,why:`Mit Teilchenbeschleunigern ist es nachgewiesen – nur in Spuren und unbezahlbar teuer.`,summary:[`Element = Zahl der Protonen: Gold 79, Blei 82.`,`Chemie ändert den Kern nicht, Kernphysik schon.`,`Die Alchemie brachte nebenbei den Phosphor.`],sources:[`Aleklett et al. 1981, Physical Review C`,`ALICE Collaboration 2025, Physical Review C`]},{id:`kitzeln`,area:`NERV`,day:4,hook:`Warum kannst du dich nicht selbst kitzeln?`,mood:`verspielt`,images:[t(`lachendes-kind`)],slides:[{text:`Probier’s: Fußsohle, Seite, Achsel – bei dir selbst passiert fast nichts. Der Grund sitzt im **Kleinhirn**: Es sagt die Folgen deiner eigenen Bewegungen voraus.`},{text:`Diese Vorhersage dämpft das Signal. So merkst du nicht jede eigene Berührung – aber sofort, wenn dich **jemand anders** anfasst. Überlebenswichtig, etwa bei einer Spinne auf dem Arm.`,cam:[50,35,1.35]},{text:`Laborversuch: Sarah-Jayne Blakemore ließ Leute sich über einen **Roboter** selbst kitzeln. Mit kleiner Verzögerung fühlte es sich wieder kitzliger an – das Gehirn konnte es nicht mehr vorhersagen.`}],verdict:`belegt`,why:`Hirnscans und Roboter-Versuche zeigen: Selbst ausgelöste Berührung wird vorhergesagt und gedämpft.`,summary:[`Das Kleinhirn sagt eigene Berührungen voraus.`,`Vorhergesagtes wird gedämpft, Fremdes nicht.`,`Mit Verzögerung kitzelt es wieder.`],sources:[`Blakemore, Wolpert & Frith 1998, Nature Neuroscience`,`Blakemore, Frith & Wolpert 1999, J Cogn Neurosci`]},{id:`everest`,area:`GEO`,day:9,hook:`Ist der Mount Everest der höchste Berg?`,mood:`episch`,ambience:`wind`,images:[t(`everest`)],slides:[{text:`Über dem **Meeresspiegel**: ja, mit 8.849 Metern. Aber es kommt darauf an, wie man misst.`},{text:`Vom **Fuß bis zur Spitze** gewinnt der Mauna Kea auf Hawaii: Er beginnt tief am Meeresboden und ist insgesamt über 10.000 Meter hoch – nur gut 4.200 davon ragen aus dem Wasser.`,cam:[50,30,1.4]},{text:`Und am weitesten vom **Erdmittelpunkt** entfernt ist der Chimborazo in Ecuador. Die Erde ist am Äquator dicker – deshalb liegt sein Gipfel gut zwei Kilometer weiter draußen als der des Everest.`}],verdict:`umstritten`,why:`Nach Meereshöhe ja – nach Gesamthöhe oder Abstand zum Erdmittelpunkt gewinnen andere Berge.`,summary:[`Höchster über dem Meer: Everest, 8.849 m.`,`Größter vom Fuß an: Mauna Kea, über 10.000 m.`,`Am weitesten draußen: Chimborazo.`],sources:[`National Geographic 2020: Neuvermessung des Everest`,`USGS: Mauna Kea`]},{id:`mauer-all`,area:`GEO`,day:73,hook:`Sieht man die Chinesische Mauer aus dem All?`,mood:`kosmisch`,ambience:`weltraum`,images:[t(`chinesische-mauer`),t(`erde-nachts`)],slides:[{text:`Ein Klassiker im Quiz: das einzige Bauwerk, das man aus dem **Weltall** sieht. Die Behauptung ist älter als die Raumfahrt – sie taucht schon in den 1930ern auf.`},{text:`Das Problem ist nicht die Länge, sondern die **Breite**: meist nur 5 bis 8 Meter, in ähnlicher Farbe wie die Landschaft. Chinas erster Raumfahrer Yang Liwei sagte 2003: Ich habe sie nicht gesehen.`,cam:[60,45,1.35]},{text:`Aus der Umlaufbahn sieht man eher **Städte bei Nacht**, Autobahnen und Flughäfen – hier Chicago von der ISS aus. Vom Mond aus erkennt man gar kein Bauwerk, nur Kontinente und Wolken.`,img:1}],verdict:`hype`,why:`Mit bloßem Auge aus dem All praktisch nicht zu erkennen – das bestätigen Astronauten.`,summary:[`Die Mauer ist zu schmal, nicht zu kurz.`,`Yang Liwei 2003: nicht gesehen.`,`Vom Mond aus: kein einziges Bauwerk.`],sources:[`NASA Earth Observatory: Great Wall from Space`,`Xinhua 2003: Yang Liwei`]},{id:`pompeji`,area:`GEO`,day:29,hook:`Erstickten die Menschen in Pompeji unter Asche?`,mood:`dunkel`,ambience:`feuer`,images:[t(`pompeji-vesuv`)],slides:[{text:`79 n. Chr. brach der **Vesuv** aus. Stundenlang regneten Bimssteine auf Pompeji, Dächer stürzten ein. Viele Bewohner flohen in dieser Zeit.`},{text:`Die meisten Zurückgebliebenen starben aber am nächsten Morgen – durch **pyroklastische Ströme**: Lawinen aus glühendem Gas und Asche, mehrere hundert Grad heiß, schneller als jedes Pferd.`,cam:[70,30,1.5]},{text:`Die berühmten **Gipsabgüsse** entstehen seit 1863: Man füllt die Hohlräume, die die Körper in der Asche hinterlassen haben. DNA-Analysen 2024 zeigten, dass manche Geschichten zu den Figuren nicht stimmen.`}],verdict:`hype`,why:`Die meisten Toten fielen der Hitze der Glutwolken zum Opfer, nicht dem Ascheregen.`,summary:[`Erst Bimsregen, dann tödliche Glutwolken.`,`Mehrere hundert Grad, schneller als ein Pferd.`,`Gipsabgüsse seit 1863, DNA-Analysen 2024.`],sources:[`Pilli et al. 2024, Current Biology`,`Parco Archeologico di Pompei`]},{id:`kleine-eiszeit`,area:`GEO`,day:71,hook:`Warum gibt es so viele alte Bilder von zugefrorenen Grachten?`,mood:`ruhig`,ambience:`wind`,images:[t(`gefrorene-gracht`)],slides:[{text:`Zwischen etwa 1300 und 1850 lag Europa in der **Kleinen Eiszeit**. Die Winter waren oft deutlich härter – Kanäle und Flüsse froren regelmäßig zu, Maler wie Bruegel zeigten Schlittschuhläufer.`},{text:`In London fror die Themse immer wieder zu, auf dem Eis fanden **Frostjahrmärkte** statt. Als Ursachen gelten vor allem Vulkanausbrüche und Phasen schwächerer Sonne.`,cam:[45,55,1.35]},{text:`Wichtig für heute: Die Kleine Eiszeit war **regional** verschieden und weltweit nur etwa ein halbes Grad kühler. Die heutige Erwärmung ist größer, schneller und überall gleichzeitig.`}],verdict:`belegt`,why:`Baumringe, Eisbohrkerne und Chroniken bestätigen die kalten Winter.`,summary:[`Kleine Eiszeit: etwa 1300–1850.`,`Frostjahrmärkte auf der Themse.`,`Heutige Erwärmung: global und schneller.`],sources:[`PAGES 2k Consortium 2019, Nature`]},{id:`erster-bug`,area:`TECH`,day:62,hook:`War der erste Computer-Bug eine echte Motte?`,mood:`verspielt`,ambience:`nacht`,images:[t(`logbuch-bug`),t(`motte`)],slides:[{text:`9. September 1947, Harvard: Im Rechner **Mark II** klemmt ein Relais. Die Techniker finden eine Motte, kleben sie ins Logbuch und schreiben: „First actual case of bug being found.“`,cam:[50,55,1.4]},{text:`Die Pointe steckt im Wort „actual“: **Bug** für einen technischen Fehler gab es längst – Thomas Edison schrieb schon 1878 von „Bugs“ in seinen Erfindungen. Die Motte war ein Witz unter Eingeweihten.`,img:1},{text:`Berühmt machte die Geschichte die Informatikerin **Grace Hopper**, die im Team arbeitete. Das Logbuch mit der Motte liegt heute im Smithsonian-Museum in Washington.`,img:0,cam:[50,50,1.1]}],verdict:`umstritten`,why:`Die Motte gab es wirklich, das Wort „Bug“ war aber schon Jahrzehnte älter.`,summary:[`1947: Motte im Harvard Mark II.`,`„Bug“ nutzte schon Edison 1878.`,`Grace Hopper machte die Geschichte berühmt.`],sources:[`Smithsonian National Museum of American History: Log Book With Computer Bug`]},{id:`gutenberg`,area:`TECH`,day:45,hook:`Hat Gutenberg den Buchdruck erfunden?`,mood:`ruhig`,ambience:`uhr`,images:[t(`gutenberg-bibel`)],slides:[{text:`Vor Gutenberg wurden Bücher in Europa meist **von Hand** abgeschrieben. Eine Bibel kostete einen Schreiber Monate. Gedruckt wurde aber schon früher – nur woanders.`},{text:`In China erfand **Bi Sheng** um 1040 bewegliche Lettern aus Ton. In Korea druckte man 1377 das Buch „Jikji“ mit Lettern aus Metall – rund 80 Jahre vor Gutenberg.`,cam:[40,45,1.4]},{text:`Gutenbergs Leistung um 1450 in Mainz war das **System**: ein Gießinstrument für gleiche Lettern, eine haltbare Metalllegierung, ölhaltige Farbe und die Presse. Damit wurde Drucken schnell und billig.`}],verdict:`umstritten`,why:`Bewegliche Lettern gab es vorher in Asien. Gutenberg erfand das System, das den Druck massentauglich machte.`,summary:[`China um 1040: Lettern aus Ton.`,`Korea 1377: Metall-Lettern (Jikji).`,`Gutenberg um 1450: Gießverfahren, Farbe, Presse.`],sources:[`UNESCO Memory of the World: Jikji`,`Gutenberg-Museum Mainz`]},{id:`gluehbirne`,area:`TECH`,day:45,hook:`Hat Edison die Glühbirne erfunden?`,mood:`hell`,images:[t(`gluehfaden`)],slides:[{text:`Bis ins 19. Jahrhundert war Licht **Feuer**: Kerzen, Öllampen, später Gas. Glühende Drähte unter Glas probierten Erfinder schon Jahrzehnte vor Edison aus.`},{text:`In England stellte **Joseph Swan** 1879 eine funktionierende Glühlampe vor – ungefähr gleichzeitig mit Edison. Die beiden stritten vor Gericht und gründeten dann eine gemeinsame Firma: Ediswan.`,cam:[50,50,1.5]},{text:`Edisons Vorsprung: ein Glühfaden, der **lange** hielt, und vor allem das ganze System aus Kraftwerk, Leitungen und Zählern. 1882 ging in New York sein erstes Kraftwerk ans Netz.`}],verdict:`umstritten`,why:`Edison verbesserte die Glühlampe entscheidend und baute das Stromnetz dazu. Erfunden haben sie mehrere.`,summary:[`Glühlampen-Versuche lange vor Edison.`,`Joseph Swan war fast gleichzeitig.`,`Edisons Stärke: haltbarer Faden + Stromnetz (1882).`],sources:[`Science Museum London: Joseph Swan`,`Smithsonian: Edison’s Pearl Street Station`]},{id:`turing-test`,area:`TECH`,day:70,hook:`Kann eine KI dich täuschen?`,mood:`kosmisch`,images:[t(`turing-statue`)],slides:[{text:`1950 schlug Alan Turing einen Test vor: Ein Mensch chattet mit zwei Unbekannten – einem Menschen und einer Maschine. Kann er sie nicht unterscheiden, hat die Maschine bestanden. Er nannte es das **Imitationsspiel**.`},{text:`2025 testeten Forscher der Uni San Diego Sprachmodelle in genau diesem Aufbau. Ein Modell mit passender Rollenanweisung wurde in **73 Prozent** der Fälle für den Menschen gehalten – öfter als die echten Menschen.`,cam:[50,30,1.4]},{text:`Heißt das, die Maschine **denkt**? Darüber streiten Fachleute. Der Test misst, ob etwas menschlich wirkt – nicht, ob es versteht. Turing selbst hielt die Frage „Können Maschinen denken?“ für zu ungenau.`}],verdict:`belegt`,why:`In kontrollierten Turing-Tests von 2025 wurden Sprachmodelle öfter für Menschen gehalten als Menschen selbst.`,summary:[`Turing 1950: das Imitationsspiel.`,`2025: KI in 73 % der Fälle für Mensch gehalten.`,`Menschlich wirken ist nicht dasselbe wie verstehen.`],sources:[`Turing 1950, Mind`,`Jones & Bergen 2025, „Large Language Models Pass the Turing Test“`]},...i,...n,...r];export{a as BITES};